package cn.mop.persistence;

import cn.mop.domain.DomainException;
import cn.mop.domain.inspection.*;
import cn.mop.domain.inspection.InspectionWorksheet.*;
import cn.mop.domain.inspection.InspectionWorksheetRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import javax.sql.DataSource;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;

/** Existing real PG and identities. Only owned synthetic drafts/templates are archived; no identity mutation or deletion. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresInspectionWorksheetIntegrationTest {
    static final String A="55000000-0000-4000-8000-000000000001",B="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static ObjectMapper mapper;static PostgresPlatformRepository platform;static PostgresInspectionWorksheetRepository repository;static PostgresInspectionTemplateRepository templates;static String admin,asset,foreignAsset;
    InspectionTemplateRepository.Entry template;final List<Entry> owned=new ArrayList<>();
    @BeforeAll static void connect()throws Exception{
        String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(6);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);
        mapper=new ObjectMapper().registerModule(new JavaTimeModule()).setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);repository=new PostgresInspectionWorksheetRepository(pool,platform);templates=new PostgresInspectionTemplateRepository(pool,platform);admin=actor("padmin");assertEquals("padmin",platform.membership(admin,B).orElseThrow().role());asset=asset(B);foreignAsset=asset(A);assertEquals(List.of(),repository.readinessProblems());
    }
    @BeforeEach void source(){var a=templateAccess();var definition=new InspectionTemplate("worksheet_custom","SYNTHETIC_WORKSHEET_"+UUID.randomUUID(),List.of(new InspectionTemplate.Item("firmware","安全合规","人工固件检查",null),new InspectionTemplate.Item("backup","配置备份","人工验证","不是扫描")));template=(InspectionTemplateRepository.Entry)platform.idempotentAuthorized(a.actorId(),a.tenantId(),"POST /integration/worksheet-template",UUID.randomUUID().toString(),definition.fingerprint(),a.permissionVersion(),()->templates.authorizeWrite(a,null),()->templates.create(a,0,definition));}
    @AfterEach void archiveOnlyOwnedDrafts(){for(Entry entry:owned){Entry current=repository.get(admin(),entry.id());assertEquals(admin,current.createdBy());assertEquals(template.id(),current.content().worksheet().template().templateId().toString());if(!current.archived())archive(current);}var a=templateAccess();var current=templates.get(a,template.id());assertTrue(current.snapshot().definition().name().startsWith("SYNTHETIC_WORKSHEET_"));if(!current.archived())templateChange(current,true);}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static String actor(String role){return platform.users().stream().filter(u->platform.membership(u.id(),A).filter(m->m.role().equals(role)).isPresent()).findFirst().orElseThrow().id();}
    static Access access(String actor,String tenant){return new Access(actor,tenant,platform.membership(actor,tenant).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static Access admin(){return access(admin,B);}
    static InspectionTemplateRepository.Access templateAccess(){var a=admin();return new InspectionTemplateRepository.Access(a.actorId(),a.tenantId(),a.permissionVersion(),a.traceId());}
    static String asset(String tenant)throws Exception{try(var c=pool.getConnection();var s=c.prepareStatement("SELECT id::text FROM public.mop_asset WHERE tenant_id=?::uuid ORDER BY id LIMIT 1")){s.setString(1,tenant);try(var r=s.executeQuery()){assertTrue(r.next());return r.getString(1);}}}
    static Content empty(){return new Content(Map.of(),null);}
    static Content filled(String note){return new Content(Map.of("firmware",new Observation(Result.ATTENTION,note,List.of())),Instant.parse("2026-01-01T01:02:03.004Z"));}
    Creation input(Content content){return new Creation(asset,template.id(),template.version(),content);}
    static Object command(Access a,String id,String route,String key,String hash,Supplier<Object> work){return platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,hash,a.permissionVersion(),()->repository.authorizeWrite(a,id),work);}
    Entry create(Content content){Access a=admin();Entry entry=(Entry)command(a,null,"POST /integration/inspection-worksheets",UUID.randomUUID().toString(),"a".repeat(64),()->repository.create(a,0,input(content)));owned.add(entry);return entry;}
    Entry update(Entry before,Content content){Access a=admin();return (Entry)command(a,before.id(),"PATCH /integration/inspection-worksheets/"+before.id(),UUID.randomUUID().toString(),"b".repeat(64),()->repository.update(a,before.id(),before.version(),content));}
    Entry archive(Entry before){Access a=admin();return (Entry)command(a,before.id(),"POST /integration/inspection-worksheets/"+before.id()+"/archive",UUID.randomUUID().toString(),"c".repeat(64),()->repository.archive(a,before.id(),before.version()));}
    Entry restore(Entry before,Content content){Access a=admin();return (Entry)command(a,before.id(),"POST /integration/inspection-worksheets/"+before.id()+"/restore",UUID.randomUUID().toString(),"d".repeat(64),()->repository.restore(a,before.id(),before.version(),content));}
    InspectionTemplateRepository.Entry templateChange(InspectionTemplateRepository.Entry before,boolean archive){var a=templateAccess();var definition=new InspectionTemplate("another_type","SYNTHETIC_WORKSHEET_CHANGED",List.of(new InspectionTemplate.Item("other","其他","另一个项目",null)));return (InspectionTemplateRepository.Entry)platform.idempotentAuthorized(a.actorId(),a.tenantId(),"POST /integration/worksheet-template/"+before.id()+"/"+(archive?"archive":"update"),UUID.randomUUID().toString(),"e".repeat(64),a.permissionVersion(),()->templates.authorizeWrite(a,before.id()),()->archive?templates.archive(a,before.id(),before.version()):templates.update(a,before.id(),before.version(),definition));}
    static List<Long> counts()throws Exception{var values=new ArrayList<Long>();try(var c=pool.getConnection();var s=c.createStatement()){for(String table:List.of("mop_inspection_worksheet","mop_inspection_worksheet_revision","mop_audit","mop_idempotency")){try(var r=s.executeQuery("SELECT count(*) FROM public."+table)){r.next();values.add(r.getLong(1));}}}return values;}
    static JsonNode json(Object value)throws Exception{return mapper.readTree(mapper.writeValueAsBytes(value));}
    @Test void createPersistsCapturedContentAndAuditReceiptAtomically()throws Exception{var before=counts();var entry=create(filled("😀\n第一行\t第二行"));assertEquals(1,entry.version());assertEquals(entry,repository.get(admin(),entry.id()));assertEquals(entry.recordedAt(),entry.createdAt());assertEquals(entry.recordedAt(),entry.updatedAt());assertEquals(1,entry.content().worksheet().summary().unanswered());assertFalse(entry.content().reportPublishable());assertEquals(List.of(before.get(0)+1,before.get(1)+1,before.get(2)+1,before.get(3)+1),counts());}
    @Test void freshRepositoryReadsCommittedFrozenData(){var entry=create(empty());var fresh=new PostgresInspectionWorksheetRepository(pool,new PostgresPlatformRepository(pool,mapper));assertEquals(entry,fresh.get(admin(),entry.id()));assertNull(entry.content().reportedPerformedAt());assertEquals("NOT_PROVIDED",entry.content().timeSource());assertEquals(2,entry.content().worksheet().summary().unanswered());assertThrows(UnsupportedOperationException.class,()->entry.content().worksheet().observations().clear());}
    @Test void updatePreservesHistoricalNullAndEmptyNotesAndImmutableBinding(){var one=create(filled(null));var two=update(one,filled(""));assertEquals(2,two.version());assertEquals(one.createdAt(),two.createdAt());assertEquals(one.content().worksheet().template(),two.content().worksheet().template());assertNotEquals(one.content().fingerprint(),two.content().fingerprint());var history=repository.history(admin(),one.id(),10,null);assertEquals(List.of(2L,1L),history.stream().map(Revision::version).toList());assertEquals(one.content(),history.get(1).content());assertNull(history.get(1).content().worksheet().observations().get("firmware").note());assertEquals(List.of(1L),repository.history(admin(),one.id(),10,2L).stream().map(Revision::version).toList());}
    @Test void staleVersionRollsBackWithoutOverwriting()throws Exception{var one=create(empty());var two=update(one,filled("current"));var before=counts();assertEquals(409,assertThrows(DomainException.class,()->update(one,filled("stale"))).status);assertEquals(two,repository.get(admin(),one.id()));assertEquals(before,counts());}
    @Test void archivePreservesContentAndRestoreRequiresExplicitCurrentVersion(){var one=create(filled("draft"));var archived=archive(one);assertTrue(archived.archived());assertEquals(one.content(),archived.content());assertEquals(409,assertThrows(DomainException.class,()->update(archived,empty())).status);var restored=restore(archived,empty());assertFalse(restored.archived());assertEquals(3,restored.version());assertNull(restored.content().reportedPerformedAt());assertEquals(409,assertThrows(DomainException.class,()->restore(restored,empty())).status);}
    @Test void otherCurrentRolesCannotReadOrWriteDrafts()throws Exception{var before=counts();for(String role:List.of("msp","viewer","tadmin")){var a=access(actor(role),A);assertEquals(403,assertThrows(DomainException.class,()->repository.list(a,null,View.ALL,10,null,null)).status);assertEquals(403,assertThrows(DomainException.class,()->command(a,null,"POST /integration/worksheet-denied",UUID.randomUUID().toString(),"a".repeat(64),()->repository.create(a,0,input(empty())))).status);}assertEquals(before,counts());}
    @Test void foreignWorksheetAssetAndTemplateAre404()throws Exception{var entry=create(empty());var a=access(admin,A);assertEquals(404,assertThrows(DomainException.class,()->repository.get(a,entry.id())).status);assertEquals(404,assertThrows(DomainException.class,()->repository.history(a,entry.id(),10,null)).status);assertEquals(404,assertThrows(DomainException.class,()->command(a,entry.id(),"POST /integration/worksheet-foreign",UUID.randomUUID().toString(),"a".repeat(64),()->repository.archive(a,entry.id(),1))).status);assertEquals(404,assertThrows(DomainException.class,()->repository.list(admin(),foreignAsset,View.ALL,10,null,null)).status);var b=admin();assertEquals(404,assertThrows(DomainException.class,()->command(b,null,"POST /integration/worksheet-foreign-asset",UUID.randomUUID().toString(),"a".repeat(64),()->repository.create(b,0,new Creation(foreignAsset,template.id(),1,empty())))).status);assertEquals(404,assertThrows(DomainException.class,()->command(a,null,"POST /integration/worksheet-foreign-template",UUID.randomUUID().toString(),"a".repeat(64),()->repository.create(a,0,new Creation(foreignAsset,template.id(),1,empty())))).status);}
    @Test void originalReceiptSurvivesWorksheetAndSourceArchiveButRechecksMembership()throws Exception{var a=admin();String key=UUID.randomUUID().toString(),route="POST /integration/worksheet-replay";Object original=command(a,null,route,key,"a".repeat(64),()->repository.create(a,0,input(filled("original"))));Entry entry=(Entry)original;owned.add(entry);archive(entry);templateChange(template,true);var before=counts();Object replay=command(a,null,route,key,"a".repeat(64),()->{throw new AssertionError("duplicate");});assertEquals(json(original),json(replay));assertEquals(before,counts());assertTrue(repository.get(a,entry.id()).archived());assertEquals(409,assertThrows(DomainException.class,()->command(a,null,route,key,"f".repeat(64),()->null)).status);var stale=new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId());assertEquals(401,assertThrows(DomainException.class,()->command(stale,null,route,key,"a".repeat(64),()->null)).status);}
    @Test void deniedAuthorizationCallbackPrecedesSavedReceiptWithoutChangingUsers()throws Exception{var a=admin();String key=UUID.randomUUID().toString(),route="POST /integration/worksheet-callback";owned.add((Entry)command(a,null,route,key,"a".repeat(64),()->repository.create(a,0,input(empty()))));assertEquals(403,assertThrows(DomainException.class,()->platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,"a".repeat(64),a.permissionVersion(),()->{throw new DomainException(403,"ACTION_FORBIDDEN","Synthetic callback denial");},()->null)).status);}
    @Test void capturedTemplateRemainsStableAfterNewDefinitionAndArchive(){var entry=create(filled("old frozen key"));var changed=templateChange(template,false);templateChange(changed,true);var updated=update(entry,filled("still original template"));assertEquals(template.snapshot(),updated.content().worksheet().template());assertEquals("firmware",updated.content().worksheet().rows().get(0).item().key());assertEquals(entry.content(),repository.history(admin(),entry.id(),10,null).get(1).content());}
    @Test void newCreationRejectsStaleOrArchivedTemplateWithoutDraftWrites()throws Exception{var changed=templateChange(template,false);var before=counts();assertEquals(409,assertThrows(DomainException.class,()->create(empty())).status);assertEquals(before,counts());template=changed;templateChange(changed,true);before=counts();assertEquals(409,assertThrows(DomainException.class,()->create(empty())).status);assertEquals(before,counts());}
    @Test void futureTimeUnknownKeysPrecisionAndMissingInputsAreRejectedWithoutWrites()throws Exception{var before=counts();for(Content input:List.of(new Content(Map.of(),Instant.parse("9999-12-31T23:59:59.999Z")),new Content(Map.of(),Instant.EPOCH.plusNanos(1)),new Content(Map.of("unknown",new Observation(Result.NORMAL,null,List.of())),null))){assertEquals(400,assertThrows(DomainException.class,()->create(input)).status);}var a=admin();assertEquals(400,assertThrows(DomainException.class,()->command(a,null,"POST /integration/worksheet-null",UUID.randomUUID().toString(),"a".repeat(64),()->repository.create(a,0,null))).status);assertEquals(before,counts());}
    @Test void callerFailureRollsBackDraftHistoryAuditAndReceipt()throws Exception{var before=counts();var a=admin();assertThrows(IllegalStateException.class,()->command(a,null,"POST /integration/worksheet-rollback",UUID.randomUUID().toString(),"a".repeat(64),()->{repository.create(a,0,input(empty()));throw new IllegalStateException("Synthetic rollback");}));assertEquals(before,counts());}
    @Test void unprotectedWritesAndNestedReadsAreRejected()throws Exception{var before=counts();var a=admin();assertThrows(IllegalStateException.class,()->repository.create(a,0,input(empty())));assertThrows(IllegalStateException.class,()->repository.authorizeWrite(a,null));assertThrows(IllegalStateException.class,()->command(a,null,"POST /integration/worksheet-nested",UUID.randomUUID().toString(),"a".repeat(64),()->repository.list(a,null,View.ALL,10,null,null)));assertEquals(before,counts());}
    @Test void boundedAssetScopedPagesAndArchiveViewsKeepDistinctIds(){for(int i=0;i<12;i++)create(empty());var first=repository.list(admin(),asset,View.CURRENT,10,null,null);assertEquals(10,first.size());var last=first.get(9);var second=repository.list(admin(),asset,View.CURRENT,10,last.createdAt(),last.id());assertEquals(2,second.size());var ids=new HashSet<String>();first.forEach(e->assertTrue(ids.add(e.id())));second.forEach(e->assertTrue(ids.add(e.id())));var current=first.get(0);archive(current);assertTrue(repository.list(admin(),asset,View.CURRENT,21,null,null).stream().noneMatch(e->e.id().equals(current.id())));assertTrue(repository.list(admin(),asset,View.ARCHIVED,21,null,null).stream().anyMatch(e->e.id().equals(current.id())));}
    @Test void successfulReadsDoNotAppendAuditOrReceipts()throws Exception{var entry=create(empty());var before=counts();repository.get(admin(),entry.id());repository.list(admin(),asset,View.ALL,10,null,null);repository.history(admin(),entry.id(),10,null);assertEquals(before,counts());}
    @Test void invalidTraceCursorBoundsAndStaleOrMissingMembershipFail()throws Exception{var entry=create(empty());var a=admin();for(int n:new int[]{0,22})assertEquals(400,assertThrows(DomainException.class,()->repository.list(a,null,View.ALL,n,null,null)).status);assertEquals(400,assertThrows(DomainException.class,()->repository.list(a,null,View.ALL,10,Instant.EPOCH,null)).status);assertEquals(400,assertThrows(DomainException.class,()->repository.list(a,null,View.ALL,10,Instant.EPOCH.plusNanos(1),UUID.randomUUID().toString())).status);assertEquals(400,assertThrows(DomainException.class,()->repository.list(new Access(a.actorId(),a.tenantId(),a.permissionVersion(),"bad trace"),null,View.ALL,10,null,null)).status);assertEquals(401,assertThrows(DomainException.class,()->repository.get(new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId()),entry.id())).status);assertEquals(401,assertThrows(DomainException.class,()->repository.get(new Access(UUID.randomUUID().toString(),B,1,a.traceId()),entry.id())).status);}
    @Test void sameKeyOnTwoConnectionsProducesOneCommitAndOriginalReceipt()throws Exception{var a=admin();String key=UUID.randomUUID().toString(),route="POST /integration/worksheet-concurrent-key";var before=counts();var executor=Executors.newFixedThreadPool(2);var ready=new CountDownLatch(2);var go=new CountDownLatch(1);try{Callable<JsonNode> action=()->{ready.countDown();assertTrue(go.await(5,TimeUnit.SECONDS));return json(command(a,null,route,key,"a".repeat(64),()->repository.create(a,0,input(empty()))));};var x=executor.submit(action);var y=executor.submit(action);assertTrue(ready.await(5,TimeUnit.SECONDS));go.countDown();var result=x.get(10,TimeUnit.SECONDS);assertEquals(result,y.get(10,TimeUnit.SECONDS));owned.add(repository.get(a,result.path("id").asText()));}finally{executor.shutdownNow();}assertEquals(List.of(before.get(0)+1,before.get(1)+1,before.get(2)+1,before.get(3)+1),counts());}
    @Test void twoConnectionsSameVersionYieldOneWinnerAndOneConflict()throws Exception{var entry=create(empty());var executor=Executors.newFixedThreadPool(2);var ready=new CountDownLatch(2);var go=new CountDownLatch(1);try{Callable<Integer> action=()->{ready.countDown();assertTrue(go.await(5,TimeUnit.SECONDS));try{update(entry,filled(UUID.randomUUID().toString()));return 200;}catch(DomainException e){return e.status;}};var x=executor.submit(action);var y=executor.submit(action);assertTrue(ready.await(5,TimeUnit.SECONDS));go.countDown();assertEquals(Set.of(200,409),Set.of(x.get(10,TimeUnit.SECONDS),y.get(10,TimeUnit.SECONDS)));}finally{executor.shutdownNow();}assertEquals(2,repository.get(admin(),entry.id()).version());assertEquals(2,repository.history(admin(),entry.id(),10,null).size());}
    @Test void actualAuditStatementFailureRollsBackWholeCommand()throws Exception{fault(true);}
    @Test void changedJsonAtActualInsertCannotReturnSuccessOrReceipt()throws Exception{fault(false);}
    void fault(boolean audit)throws Exception{
        DataSource injected=(DataSource)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{DataSource.class},(proxy,method,args)->{
            if(method.getName().equals("getConnection")){Connection real=pool.getConnection();return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{
                if(cm.getName().equals("prepareStatement")&&ca[0] instanceof String sql){if(audit&&sql.startsWith("INSERT INTO public.mop_audit"))throw new SQLException("Synthetic audit rejection","22012");if(!audit&&sql.startsWith("INSERT INTO public.mop_inspection_worksheet_revision")){PreparedStatement statement=(PreparedStatement)cm.invoke(real,ca);return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{PreparedStatement.class},(sp,sm,sa)->{if(sm.getName().equals("setString")&&Integer.valueOf(10).equals(sa[0]))sa=new Object[]{10,"[]"};try{return sm.invoke(statement,sa);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});}}
                try{return cm.invoke(real,ca);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}
            });}try{return method.invoke(pool,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}
        });
        var otherPlatform=new PostgresPlatformRepository(injected,mapper);var other=new PostgresInspectionWorksheetRepository(injected,otherPlatform);var a=admin();var before=counts();assertEquals(503,assertThrows(DomainException.class,()->otherPlatform.idempotentAuthorized(a.actorId(),a.tenantId(),"POST /integration/worksheet-fault",UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->other.authorizeWrite(a,null),()->other.create(a,0,input(filled("synthetic fault"))))).status);assertEquals(before,counts());
    }
}
